@Bean
SecurityFilterChain api(HttpSecurity http) throws Exception {
    http.authorizeHttpRequests(auth -> auth
            .requestMatchers("/health").permitAll()          // explicit public surface
            .anyRequest().authenticated())                    // default deny
        .oauth2ResourceServer(o -> o.jwt(Customizer.withDefaults())); // mechanism
    return http.build();
}

