@Provider
@Authenticated                       // @NameBinding annotation
public class AuthFilter implements ContainerRequestFilter {
    @Override
    public void filter(ContainerRequestContext ctx) {
        var securityContext = tokens.verify(ctx.getHeaderString("Authorization")); // delegated
        if (securityContext == null) {
            ctx.abortWith(Response.status(Response.Status.UNAUTHORIZED).build()); // challenge
        } else {
            ctx.setSecurityContext(securityContext);   // request-scoped principal
        }
    }
}
